 function recipientToken(value:string){const i=Math.max(value.lastIndexOf(","),value.lastIndexOf(";"),value.lastIndexOf("\n"));return value.slice(i+1).trim().toLowerCase()}
 function recipientSuggestions(value:string){const token=recipientToken(value),used=new Set([...splitAddresses(to),...splitAddresses(cc),...splitAddresses(bcc)].map(x=>x.toLowerCase()));return contacts.filter(c=>!used.has(c.email.toLowerCase())&&(!token||c.email.toLowerCase().includes(token)||(c.name||"").toLowerCase().includes(token))).sort((a,b)=>{if(!token)return (b.score||0)-(a.score||0)||String(b.lastSeen||"").localeCompare(String(a.lastSeen||""));const ae=a.email.toLowerCase(),be=b.email.toLowerCase(),an=(a.name||"").toLowerCase(),bn=(b.name||"").toLowerCase(),ar=ae===token||an===token?0:ae.startsWith(token)||an.startsWith(token)?1:2,br=be===token||bn===token?0:be.startsWith(token)||bn.startsWith(token)?1:2;return ar-br||(b.score||0)-(a.score||0)||String(b.lastSeen||"").localeCompare(String(a.lastSeen||""))}).slice(0,6)}
