  function replaceRecipientToken(value:string,email:string){const i=Math.max(value.lastIndexOf(","),value.lastIndexOf(";"),value.lastIndexOf("\n"));const prefix=i>=0?value.slice(0,i+1).trimEnd()+" ":"";return prefix+email+", "}
